#!/usr/bin/env python3
"""
Metro Cell Tower Coverage Expansion - PySCIPOpt Solver
"""

import csv
import json
import os
import sys
import time

from pyscipopt import Model, quicksum, SCIP_RESULT, SCIP_STATUS


def read_csv(path):
    with open(path, "r") as f:
        return list(csv.DictReader(f))


def main():
    data_dir = "/app/data"
    out_dir = "/app/submissions"
    os.makedirs(out_dir, exist_ok=True)

    # Read config
    with open(os.path.join(data_dir, "config.json"), "r") as f:
        config = json.load(f)

    budget = float(config["budget_kusd"])
    min_fiber = int(config["min_fiber_ready_towers"])
    min_backup = int(config["min_backup_power_towers"])
    crit_floor = float(config["critical_coverage_floor"])
    crit_max_lat = float(config["critical_max_latency_ms"])
    crit_resilient = bool(config["critical_requires_resilient_tower"])
    opex_w = float(config["opex_penalty_weight"])
    lease_w = float(config["backhaul_lease_penalty_weight"])
    sig_mult = float(config["signal_value_multiplier"])
    tol = float(config.get("feasibility_tolerance", 1e-5))

    # Read data
    towers = read_csv(os.path.join(data_dir, "candidate_towers.csv"))
    areas = read_csv(os.path.join(data_dir, "demand_areas.csv"))
    links = read_csv(os.path.join(data_dir, "coverage_links.csv"))
    bh_groups = read_csv(os.path.join(data_dir, "backhaul_groups.csv"))
    dist_reqs = read_csv(os.path.join(data_dir, "district_requirements.csv"))
    type_rules = read_csv(os.path.join(data_dir, "tower_type_rules.csv"))
    interf_pairs = read_csv(os.path.join(data_dir, "interference_pairs.csv"))
    chan_div = read_csv(os.path.join(data_dir, "district_channel_diversity.csv"))

    # Index structures
    tower_ids = [t["tower_id"] for t in towers]
    area_ids = [a["area_id"] for a in areas]
    tower_idx = {t["tower_id"]: i for i, t in enumerate(towers)}
    area_idx = {a["area_id"]: i for i, a in enumerate(areas)}

    # Tower attributes
    t_district = {t["tower_id"]: t["district"] for t in towers}
    t_type = {t["tower_id"]: t["tower_type"] for t in towers}
    t_build = {t["tower_id"]: float(t["build_cost_kusd"]) for t in towers}
    t_opex = {t["tower_id"]: float(t["annual_opex_kusd"]) for t in towers}
    t_cap = {t["tower_id"]: float(t["capacity_mbps"]) for t in towers}
    t_fiber = {t["tower_id"]: int(t["fiber_ready"]) for t in towers}
    t_backup = {t["tower_id"]: int(t["backup_power"]) for t in towers}
    t_chan = {t["tower_id"]: t["radio_channel"] for t in towers}
    t_bh = {t["tower_id"]: t["backhaul_group"] for t in towers}
    t_maxassign = {t["tower_id"]: int(t["max_area_assignments"]) for t in towers}

    # Area attributes
    a_district = {a["area_id"]: a["district"] for a in areas}
    a_pop = {a["area_id"]: float(a["population"]) for a in areas}
    a_dev = {a["area_id"]: float(a["enterprise_devices"]) for a in areas}
    a_crit = {a["area_id"]: int(a["critical_facility"]) for a in areas}
    a_minsig = {a["area_id"]: float(a["minimum_signal_score"]) for a in areas}
    a_rv = {a["area_id"]: float(a["resident_value"]) for a in areas}
    a_dv = {a["area_id"]: float(a["device_value"]) for a in areas}

    # Backhaul group attributes
    bh_ids = [g["backhaul_group"] for g in bh_groups]
    bh_idx = {g["backhaul_group"]: i for i, g in enumerate(bh_groups)}
    bh_cap = {g["backhaul_group"]: float(g["capacity_mbps"]) for g in bh_groups}
    bh_maxt = {g["backhaul_group"]: int(g["max_active_towers"]) for g in bh_groups}
    bh_minfib = {g["backhaul_group"]: int(g["min_fiber_ready_towers"]) for g in bh_groups}
    bh_lease = {g["backhaul_group"]: float(g["lease_cost_kusd"]) for g in bh_groups}

    # District requirements
    districts = sorted(set(a_district.values()))
    dist_pop_share = {r["district"]: float(r["min_population_coverage_share"]) for r in dist_reqs}
    dist_dev_floor = {r["district"]: float(r["min_enterprise_devices"]) for r in dist_reqs}
    dist_crit_min = {r["district"]: int(r["min_critical_areas"]) for r in dist_reqs}

    # Tower type rules
    type_min = {r["tower_type"]: int(r["min_active"]) for r in type_rules}
    type_max = {r["tower_type"]: int(r["max_active"]) for r in type_rules}

    # Channel diversity
    chan_div_min_active = {r["district"]: int(r["min_active_channels"]) for r in chan_div}
    chan_div_min_resil = {r["district"]: int(r["min_resilient_channels"]) for r in chan_div}
    chan_div_alt = {r["district"]: int(r["critical_requires_alt_channel"]) for r in chan_div}

    # Interference pairs
    interf = []
    for p in interf_pairs:
        t1, t2 = p["tower_id"], p["conflict_tower_id"]
        mx = int(p["max_built"])
        interf.append((t1, t2, mx))

    # Pre-filter links
    valid_links = []
    for lk in links:
        tid, aid = lk["tower_id"], lk["area_id"]
        sig = float(lk["signal_score"])
        dem = float(lk["demand_mbps"])
        lat = float(lk["latency_ms"])
        # Signal check
        if sig < a_minsig[aid] - tol:
            continue
        # Critical latency
        if a_crit[aid] == 1 and lat > crit_max_lat + tol:
            continue
        # Critical resilient tower
        if a_crit[aid] == 1 and crit_resilient:
            if not (t_fiber[tid] == 1 and t_backup[tid] == 1):
                continue
        valid_links.append((tid, aid, sig, dem, lat))

    # Build link index
    link_list = [(t, a) for (t, a, s, d, l) in valid_links]
    link_sig = {(t, a): s for (t, a, s, d, l) in valid_links}
    link_dem = {(t, a): d for (t, a, s, d, l) in valid_links}
    link_lat = {(t, a): l for (t, a, s, d, l) in valid_links}

    # Compute link values
    # value = rv * pop + dv * dev + crit_bonus + sig_mult * sig * pop - lat_penalty
    # crit_bonus: use 5000 per critical area served (reasonable scale)
    # lat_penalty: 10 per ms
    link_val = {}
    for (t, a) in link_list:
        s = link_sig[(t, a)]
        l = link_lat[(t, a)]
        v = (a_rv[a] * a_pop[a] + a_dv[a] * a_dev[a]
             + (5000.0 if a_crit[a] == 1 else 0.0)
             + sig_mult * s * a_pop[a]
             - 10.0 * l)
        link_val[(t, a)] = v

    # Create SCIP model
    model = Model("cell_tower_coverage")
    model.setMinimize(False)  # maximize

    # Time limit
    time_limit = 300.0
    env_tl = os.environ.get("ORCLAW_SOLVE_TIME_LIMIT_SECONDS")
    if env_tl:
        time_limit = min(time_limit, float(env_tl))
    model.setRealParam("limits/time", time_limit)
    model.setRealParam("gap/rel", 0.0005)

    # Decision variables
    x = {}
    for t in tower_ids:
        x[t] = model.addVar(name=f"x_{t}", vtype="B", obj=0.0)

    z = {}
    for (t, a) in link_list:
        z[(t, a)] = model.addVar(name=f"z_{t}_{a}", vtype="B", obj=0.0)

    # Backhaul group usage
    u = {}
    for g in bh_ids:
        u[g] = model.addVar(name=f"u_{g}", vtype="B", obj=0.0)

    # Channel diversity auxiliary variables
    # For each district and channel: is there an active tower with that channel in that district?
    # For resilient: active tower with backup power
    dist_channels = {}
    for d in districts:
        chans = set(t_chan[t] for t in tower_ids if t_district[t] == d)
        dist_channels[d] = sorted(chans)

    ch_var = {}  # (district, channel) -> var
    ch_res_var = {}  # (district, channel) -> var for resilient
    for d in districts:
        for c in dist_channels[d]:
            ch_var[(d, c)] = model.addVar(name=f"ch_{d}_{c}", vtype="B", obj=0.0)
            ch_res_var[(d, c)] = model.addVar(name=f"chr_{d}_{c}", vtype="B", obj=0.0)

    # --- Objective ---
    # Maximize sum of link values - opex - lease
    obj_terms = []
    for (t, a) in link_list:
        obj_terms.append(link_val[(t, a)] * z[(t, a)])
    for t in tower_ids:
        obj_terms.append(-opex_w * t_opex[t] * x[t])
    for g in bh_ids:
        obj_terms.append(-lease_w * bh_lease[g] * u[g])

    model.setObjective(quicksum(obj_terms), sense="maximize")

    # --- Constraints ---

    # 1. Link activation: z <= x
    for (t, a) in link_list:
        model.addCons(z[(t, a)] <= x[t], name=f"link_act_{t}_{a}")

    # 2. One tower per area
    for a in area_ids:
        links_for_a = [(t, a) for (t, a) in link_list]
        if links_for_a:
            model.addCons(quicksum(z[(t, a)] for (t, a) in links_for_a) <= 1,
                          name=f"one_tower_{a}")

    # 3. Budget
    model.addCons(quicksum(t_build[t] * x[t] for t in tower_ids) <= budget,
                  name="budget")

    # 4. Tower assignment limit
    for t in tower_ids:
        links_for_t = [(t, a) for (t, a) in link_list]
        if links_for_t:
            model.addCons(quicksum(z[(t, a)] for (t, a) in links_for_t) <= t_maxassign[t] * x[t],
                          name=f"assign_lim_{t}")

    # 5. Tower capacity
    for t in tower_ids:
        links_for_t = [(t, a) for (t, a) in link_list]
        if links_for_t:
            model.addCons(quicksum(link_dem[(t, a)] * z[(t, a)] for (t, a) in links_for_t) <= t_cap[t] * x[t],
                          name=f"cap_{t}")

    # 6. Global fiber minimum
    fiber_towers = [t for t in tower_ids if t_fiber[t] == 1]
    if fiber_towers:
        model.addCons(quicksum(x[t] for t in fiber_towers) >= min_fiber, name="min_fiber")

    # 7. Global backup minimum
    backup_towers = [t for t in tower_ids if t_backup[t] == 1]
    if backup_towers:
        model.addCons(quicksum(x[t] for t in backup_towers) >= min_backup, name="min_backup")

    # 8. Critical coverage floor
    crit_areas = [a for a in area_ids if a_crit[a] == 1]
    total_crit_pop = sum(a_pop[a] for a in crit_areas)
    if crit_areas and total_crit_pop > 0:
        crit_served_pop = quicksum(
            a_pop[a] * quicksum(z[(t, a)] for (t, a) in link_list if a == a)
            for a in crit_areas
        )
        model.addCons(crit_served_pop >= crit_floor * total_crit_pop, name="crit_floor")

    # 9. District population coverage share
    for d in districts:
        dist_areas = [a for a in area_ids if a_district[a] == d]
        total_pop = sum(a_pop[a] for a in dist_areas)
        if total_pop > 0:
            served_pop = quicksum(
                a_pop[a] * quicksum(z[(t, a)] for (t, a) in link_list if a == a)
                for a in dist_areas
            )
            model.addCons(served_pop >= dist_pop_share[d] * total_pop,
                          name=f"pop_share_{d}")

    # 10. District enterprise device floor
    for d in districts:
        dist_areas = [a for a in area_ids if a_district[a] == d]
        served_dev = quicksum(
            a_dev[a] * quicksum(z[(t, a)] for (t, a) in link_list if a == a)
            for a in dist_areas
        )
        model.addCons(served_dev >= dist_dev_floor[d], name=f"dev_floor_{d}")

    # 11. District critical area minimum
    for d in districts:
        dist_crit = [a for a in area_ids if a_district[a] == d and a_crit[a] == 1]
        if dist_crit:
            served_crit = quicksum(
                quicksum(z[(t, a)] for (t, a) in link_list if a == a)
                for a in dist_crit
            )
            model.addCons(served_crit >= dist_crit_min[d], name=f"crit_min_{d}")

    # 12. Tower type bounds
    all_types = sorted(set(t_type[t] for t in tower_ids))
    for ty in all_types:
        type_towers = [t for t in tower_ids if t_type[t] == ty]
        if type_towers:
            if ty in type_min:
                model.addCons(quicksum(x[t] for t in type_towers) >= type_min[ty],
                              name=f"type_min_{ty}")
            if ty in type_max:
                model.addCons(quicksum(x[t] for t in type_towers) <= type_max[ty],
                              name=f"type_max_{ty}")

    # 13. Backhaul group constraints
    for g in bh_ids:
        g_towers = [t for t in tower_ids if t_bh[t] == g]
        if not g_towers:
            continue
        # Max active towers
        model.addCons(quicksum(x[t] for t in g_towers) <= bh_maxt[g], name=f"bh_max_{g}")
        # Min fiber ready when used
        g_fiber = [t for t in g_towers if t_fiber[t] == 1]
        if g_fiber:
            model.addCons(quicksum(x[t] for t in g_fiber) >= bh_minfib[g] * u[g],
                          name=f"bh_fib_{g}")
        # u_g <= sum x_t
        model.addCons(u[g] <= quicksum(x[t] for t in g_towers), name=f"bh_use_{g}")
        # Backhaul capacity
        g_links = [(t, a) for (t, a) in link_list if t_bh[t] == g]
        if g_links:
            model.addCons(quicksum(link_dem[(t, a)] * z[(t, a)] for (t, a) in g_links) <= bh_cap[g] * u[g],
                          name=f"bh_cap_{g}")

    # 14. District channel diversity
    for d in districts:
        d_towers = [t for t in tower_ids if t_district[t] == d]
        if not d_towers:
            continue
        for c in dist_channels[d]:
            c_towers = [t for t in d_towers if t_chan[t] == c]
            if c_towers:
                # ch_var >= x_t for each tower with channel c
                for t in c_towers:
                    model.addCons(ch_var[(d, c)] >= x[t], name=f"ch_lb_{d}_{c}_{t}")
                # ch_var <= sum x_t
                model.addCons(ch_var[(d, c)] <= quicksum(x[t] for t in c_towers),
                              name=f"ch_ub_{d}_{c}")
            # Resilient channel var
            c_res_towers = [t for t in c_towers if t_backup[t] == 1]
            if c_res_towers:
                for t in c_res_towers:
                    model.addCons(ch_res_var[(d, c)] >= x[t], name=f"chr_lb_{d}_{c}_{t}")
                model.addCons(ch_res_var[(d, c)] <= quicksum(x[t] for t in c_res_towers),
                              name=f"chr_ub_{d}_{c}")
            else:
                model.addCons(ch_res_var[(d, c)] == 0, name=f"chr_zero_{d}_{c}")

        # Min active channels
        min_ch = chan_div_min_active.get(d, 0)
        if min_ch > 0:
            model.addCons(quicksum(ch_var[(d, c)] for c in dist_channels[d]) >= min_ch,
                          name=f"min_ch_{d}")
        # Min resilient channels
        min_rc = chan_div_min_resil.get(d, 0)
        if min_rc > 0:
            model.addCons(quicksum(ch_res_var[(d, c)] for c in dist_channels[d]) >= min_rc,
                          name=f"min_rc_{d}")

    # 15. Interference pairs
    for i, (t1, t2, mx) in enumerate(interf):
        if t1 in x and t2 in x:
            model.addCons(x[t1] + x[t2] <= mx, name=f"interf_{i}")

    # 16. Critical alternate channel (inactive in this instance, all 0)
    # All districts have critical_requires_alt_channel = 0, so skip.

    # Solve
    print("Solving model...")
    t0 = time.time()
    model.optimize()
    elapsed = time.time() - t0
    print(f"Solve time: {elapsed:.2f}s")

    status = model.getStatus()
    print(f"Status: {status}")

    if status not in ("optimal", "bestsollimit", "timelimit", "gap"):
        # Try to get best solution anyway
        pass

    if model.getNsolns() == 0:
        print("No feasible solution found!")
        sys.exit(1)

    # Extract solution
    best_obj = model.getObjval()
    print(f"Objective: {best_obj:.6f}")

    built_towers = set()
    for t in tower_ids:
        if model.getVal(x[t]) > 0.5:
            built_towers.add(t)

    served_links = []
    for (t, a) in link_list:
        if model.getVal(z[(t, a)]) > 0.5:
            served_links.append((t, a))

    # Write solution
    sol_path = os.path.join(out_dir, "solution.csv")
    with open(sol_path, "w", newline="") as f:
        writer = csv.writer(f)
        writer.writerow(["row_type", "tower_id", "area_id", "value"])
        for t in sorted(built_towers):
            writer.writerow(["build", t, "", 1])
        for (t, a) in sorted(served_links):
            writer.writerow(["serve", t, a, 1])

    print(f"Solution written to {sol_path}")
    print(f"Built towers: {len(built_towers)}")
    print(f"Served areas: {len(served_links)}")

    # Validation
    print("\n--- Validation ---")
    # Check budget
    total_build = sum(t_build[t] for t in built_towers)
    print(f"Total build cost: {total_build:.1f} (budget: {budget})")
    assert total_build <= budget + tol, "Budget violated!"

    # Check each served area has at most one tower
    area_count = {}
    for (t, a) in served_links:
        area_count[a] = area_count.get(a, 0) + 1
    for a, c in area_count.items():
        assert c <= 1, f"Area {a} served by {c} towers!"

    # Check served links use built towers
    for (t, a) in served_links:
        assert t in built_towers, f"Link {t}-{a} uses unbuilt tower {t}!"

    # Check tower assignment limits
    tower_assign = {}
    for (t, a) in served_links:
        tower_assign[t] = tower_assign.get(t, 0) + 1
    for t, c in tower_assign.items():
        assert c <= t_maxassign[t], f"Tower {t} has {c} assignments (max {t_maxassign[t]})"

    # Check tower capacity
    tower_load = {}
    for (t, a) in served_links:
        tower_load[t] = tower_load.get(t, 0.0) + link_dem[(t, a)]
    for t, load in tower_load.items():
        assert load <= t_cap[t] + tol, f"Tower {t} load {load:.1f} exceeds cap {t_cap[t]}"

    # Check critical coverage
    crit_served = sum(a_pop[a] for (t, a) in served_links if a_crit[a] == 1)
    print(f"Critical population served: {crit_served:.0f} / {total_crit_pop:.0f} ({crit_served/total_crit_pop:.2%})")
    assert crit_served >= crit_floor * total_crit_pop - tol, "Critical floor violated!"

    # Check district requirements
    for d in districts:
        dist_areas = [a for a in area_ids if a_district[a] == d]
        total_pop_d = sum(a_pop[a] for a in dist_areas)
        served_pop_d = sum(a_pop[a] for (t, a) in served_links if a_district[a] == d)
        served_dev_d = sum(a_dev[a] for (t, a) in served_links if a_district[a] == d)
        served_crit_d = sum(1 for (t, a) in served_links if a_district[a] == d and a_crit[a] == 1)
        print(f"  {d}: pop {served_pop_d:.0f}/{total_pop_d:.0f} ({served_pop_d/total_pop_d:.1%}), "
              f"dev {served_dev_d:.0f}/{dist_dev_floor[d]:.0f}, crit {served_crit_d}/{dist_crit_min[d]}")
        assert served_pop_d >= dist_pop_share[d] * total_pop_d - tol, f"Pop share violated for {d}"
        assert served_dev_d >= dist_dev_floor[d] - tol, f"Dev floor violated for {d}"
        assert served_crit_d >= dist_crit_min[d], f"Crit min violated for {d}"

    # Check tower types
    for ty in all_types:
        count = sum(1 for t in built_towers if t_type[t] == ty)
        lo = type_min.get(ty, 0)
        hi = type_max.get(ty, 999)
        print(f"  Type {ty}: {count} active (bounds [{lo}, {hi}])")
        assert lo <= count <= hi, f"Type bound violated for {ty}"

    # Check fiber/backup minimums
    fib_count = sum(1 for t in built_towers if t_fiber[t] == 1)
    bak_count = sum(1 for t in built_towers if t_backup[t] == 1)
    print(f"  Fiber towers: {fib_count}/{min_fiber}, Backup towers: {bak_count}/{min_backup}")
    assert fib_count >= min_fiber, "Fiber minimum violated!"
    assert bak_count >= min_backup, "Backup minimum violated!"

    # Check interference
    for (t1, t2, mx) in interf:
        if t1 in built_towers and t2 in built_towers:
            assert mx >= 2, f"Interference violated: {t1} and {t2} both built"

    print("\nAll validation checks passed!")


if __name__ == "__main__":
    main()
